const raw = $json.body ?? $json;
let body = raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (error) {
    body = {};
  }
}

const text = (value) => String(value ?? '').trim();
const money = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.round(parsed * 100) / 100 : NaN;
};
const escapeFormula = (value) => String(value).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
const fail = (error, message, extra = {}) => [{ json: { ok: false, error, message, ...extra } }];

const operationId = text(body.operationId);
const empresaId = text(body.empresaId);
const cajaId = text(body.cajaId);
const cajaSesionId = text(body.cajaSesionId);
const cashier = text(body.cashier || body.usuarioId);
const customerId = text(body.customerId) || null;
const customerName = text(body.customerName) || 'Consumidor final';
const paymentMethod = text(body.paymentMethod).toLowerCase();
const allowedPayments = ['cash', 'card', 'transfer', 'efectivo', 'tarjeta', 'transferencia'];
const discountPercent = money(body.discountPercent ?? 0);
const cashReceived = money(body.cashReceived ?? 0);
const receivedItems = Array.isArray(body.items) ? body.items : [];

if (!operationId || !empresaId || !cajaSesionId || !cashier || receivedItems.length === 0 || !allowedPayments.includes(paymentMethod)) {
  return fail('INVALID_PAYLOAD', 'Faltan datos obligatorios para registrar la venta');
}

if (!Number.isFinite(discountPercent) || discountPercent < 0 || discountPercent > 100) {
  return fail('INVALID_PAYLOAD', 'Faltan datos obligatorios para registrar la venta');
}

const normalizedItems = [];
for (const item of receivedItems) {
  const productId = text(item.productId || item.id);
  const quantity = Number(item.quantity);
  if (!productId || !Number.isFinite(quantity) || quantity <= 0) {
    return fail('INVALID_PAYLOAD', 'Faltan datos obligatorios para registrar la venta');
  }
  normalizedItems.push({ productId, quantity });
}

if ((paymentMethod === 'cash' || paymentMethod === 'efectivo') && (!Number.isFinite(cashReceived) || cashReceived < 0)) {
  return fail('INVALID_PAYLOAD', 'Faltan datos obligatorios para registrar la venta');
}

const productFormula = `OR(${normalizedItems.map((item) => `RECORD_ID() = "${escapeFormula(item.productId)}"`).join(', ')})`;

return [{
  json: {
    ok: true,
    operationId,
    empresaId,
    cajaId,
    cajaSesionId,
    cashier,
    customerId,
    customerName,
    paymentMethod,
    discountPercent,
    cashReceived,
    createdAt: (() => { const candidate = body.createdAt ? new Date(body.createdAt) : new Date(); return Number.isNaN(candidate.getTime()) ? new Date().toISOString() : candidate.toISOString(); })(),
    items: normalizedItems,
    operationFormula: `({OperationId} & "") = "${escapeFormula(operationId)}"`,
    cashSessionFormula: `AND(RECORD_ID() = "${escapeFormula(cajaSesionId)}", ({estado} & "") = "ABIERTA")`,
    productFormula
  }
}];

try {
  const validation = $items('Validacion')[0]?.json || {};
  const rows = $items('BuscarVentaOperationId');
  const queryError = rows.find((item) => item.json && (item.json.error || item.json.message) && !item.json.id);

  if (queryError) {
    return [{ json: { ok: false, processable: false, error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta' } }];
  }

  const existing = rows.find((item) => item.json && item.json.id);
  if (!existing) {
    return [{ json: { ...validation, processable: true } }];
  }

  const fields = existing.json.fields || existing.json;
  const estado = String(fields.Estado || '').toUpperCase();
  const total = Number(fields.Total || 0);

  if (estado === 'CONFIRMADA') {
    return [{ json: { ok: true, processable: false, ventaId: existing.json.id, operationId: validation.operationId, total, idempotent: true } }];
  }

  return [{ json: { ok: false, processable: false, error: 'SALE_ALREADY_EXISTS', message: 'Ya existe una venta con este OperationId y no se creara un duplicado', ventaId: existing.json.id, operationId: validation.operationId, estado: estado || 'PENDIENTE' } }];
} catch (error) {
  return [{ json: { ok: false, processable: false, error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta' } }];
}

try {
  const sale = $items('DecidirIdempotencia')[0]?.json || {};
  const rows = $items('BuscarCajaAbierta');
  const queryError = rows.find((item) => item.json && (item.json.error || item.json.message) && !item.json.id);
  if (queryError) {
    return [{ json: { ok: false, cashOpen: false, error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta' } }];
  }
  const session = rows.find((item) => item.json && item.json.id);
  if (!session) {
    return [{ json: { ok: false, cashOpen: false, error: 'CASH_REGISTER_CLOSED', message: 'La caja no esta abierta' } }];
  }
  return [{ json: { ...sale, cashOpen: true } }];
} catch (error) {
  return [{ json: { ok: false, cashOpen: false, error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta' } }];
}

try {
  const sale = $items('ValidarCajaAbierta')[0]?.json || {};
  const records = $items('BuscarProductos').filter((item) => item.json && item.json.id && !item.json.error);
  const queryError = $items('BuscarProductos').find((item) => item.json && (item.json.error || item.json.message) && !item.json.id);
  if (queryError) {
    return [{ json: { ok: false, error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta' } }];
  }

  const byId = new Map(records.map((item) => [item.json.id, item.json.fields || item.json]));
  const number = (value, fallback = 0) => {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  };
  const money = (value) => Math.round(Number(value || 0) * 100) / 100;
  const textValue = (value) => value && typeof value === 'object' && 'text' in value ? String(value.text || '') : String(value || '');

  const serverItems = [];
  const detailRows = [];
  const stockRows = [];
  const stockUpdates = [];

  for (const item of sale.items) {
    const record = byId.get(item.productId);
    if (!record) {
      return [{ json: { ok: false, error: 'PRODUCT_NOT_FOUND', message: 'Uno de los productos no existe', productId: item.productId } }];
    }

    const stockBefore = number(record['Stock Actual']);
    const unitPrice = number(record.Importe, number(record['Precio x Kg']));
    const quantity = number(item.quantity);

    if (stockBefore < quantity) {
      return [{ json: { ok: false, error: 'INSUFFICIENT_STOCK', message: 'Stock insuficiente para completar la venta', productId: item.productId, available: stockBefore, requested: quantity } }];
    }

    if (!Number.isFinite(unitPrice) || unitPrice <= 0) {
      return [{ json: { ok: false, error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta', productId: item.productId } }];
    }

    const stockAfter = stockBefore - quantity;
    const productName = String(record.Name || 'Producto');
    const barcode = textValue(record['Codigo de Barras']);
    const lineTotal = money(unitPrice * quantity);

    serverItems.push({ productId: item.productId, name: productName, barcode, quantity, unitPrice, lineTotal });
    detailRows.push({ Venta: null, Producto: [item.productId], ProductoNombre: productName, CodigoBarras: barcode, Cantidad: quantity, PrecioUnitario: unitPrice, TotalLinea: lineTotal, Estado: 'ACTIVO' });
    stockRows.push({ OperationId: sale.operationId, Producto: [item.productId], Tipo: 'VENTA', Cantidad: -quantity, StockAntes: stockBefore, StockDespues: stockAfter, Origen: 'VENTA', Venta: null, Responsable: sale.cashier, Estado: 'ACTIVO' });
    stockUpdates.push({ id: item.productId, stockBefore, stockAfter });
  }

  const subtotal = money(serverItems.reduce((sum, item) => sum + item.lineTotal, 0));
  const discountAmount = money(subtotal * (sale.discountPercent / 100));
  const total = money(subtotal - discountAmount);
  const change = sale.paymentMethod === 'cash' || sale.paymentMethod === 'efectivo' ? money(Math.max(0, sale.cashReceived - total)) : 0;

  if ((sale.paymentMethod === 'cash' || sale.paymentMethod === 'efectivo') && sale.cashReceived < total) {
    return [{ json: { ok: false, error: 'INVALID_PAYLOAD', message: 'Faltan datos obligatorios para registrar la venta' } }];
  }

  return [{ json: { ...sale, items: serverItems, subtotal, discountAmount, total, change, detailRows, stockRows, stockUpdates } }];
} catch (error) {
  return [{ json: { ok: false, error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta' } }];
}

const sale = $items('ValidarProductosPrecios')[0]?.json || {};
if (!$json || $json.error || !$json.id) {
  return [{ json: { ok: false, canContinue: false, error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta', operationId: sale.operationId } }];
}
return [{ json: { ...sale, canContinue: true, ventaId: $json.id } }];

const sale = $items('VerificarVentaCreada')[0]?.json || {};
const created = $items('CrearDetalleVenta').filter((item) => item.json && item.json.id && !item.json.error);
if (created.length !== (sale.detailRows || []).length) {
  return [{ json: { ok: false, canContinue: false, failedStep: 'DETALLE_VENTA', error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta', operationId: sale.operationId, ventaId: sale.ventaId, created: { detalleIds: created.map((item) => item.json.id) }, stockUpdates: [] } }];
}
return [{ json: { ...sale, canContinue: true, detalleIds: created.map((item) => item.json.id) } }];

const sale = $items('VerificarDetalle')[0]?.json || {};
const created = $items('CrearMovimientosStock').filter((item) => item.json && item.json.id && !item.json.error);
if (created.length !== (sale.stockRows || []).length) {
  return [{ json: { ok: false, canContinue: false, failedStep: 'MOVIMIENTOS_STOCK', error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta', operationId: sale.operationId, ventaId: sale.ventaId, created: { detalleIds: sale.detalleIds || [], stockMovimientoIds: created.map((item) => item.json.id) }, stockUpdates: [] } }];
}
return [{ json: { ...sale, canContinue: true, stockMovimientoIds: created.map((item) => item.json.id) } }];

const sale = $items('VerificarMovimientosStock')[0]?.json || {};
const updated = $items('ActualizarStockProduccion').filter((item) => item.json && item.json.id && !item.json.error);
if (updated.length !== (sale.stockUpdates || []).length) {
  return [{ json: { ok: false, canContinue: false, failedStep: 'PRODUCCION_STOCK', error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta', operationId: sale.operationId, ventaId: sale.ventaId, stockUpdates: sale.stockUpdates || [] } }];
}
return [{ json: { ...sale, canContinue: true } }];

const sale = $items('VerificarStockActualizado')[0]?.json || {};
return [{ json: {
  venta_id: sale.ventaId,
  caja_sesion_id: sale.cajaSesionId,
  usuario_id: sale.cashier,
  tipo: 'INGRESO',
  origen: 'VENTA',
  importe: sale.total,
  estado: 'ACTIVO',
  motivo: 'Venta POS',
  operation_id: sale.operationId,
  fecha_hora: sale.createdAt
} }];

const sale = $items('VerificarStockActualizado')[0]?.json || {};
if (!$json || $json.error || !$json.id) {
  return [{ json: { ok: false, canContinue: false, failedStep: 'MOVIMIENTOS_CAJA', error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta', operationId: sale.operationId, ventaId: sale.ventaId, stockUpdates: sale.stockUpdates || [] } }];
}
return [{ json: { ...sale, canContinue: true, cajaMovimientoId: $json.id } }];

const sale = $items('VerificarMovimientoCaja')[0]?.json || {};
if (!$json || $json.error || !$json.id) {
  return [{ json: { ok: false, canContinue: false, failedStep: 'CONFIRMAR_VENTA', error: 'SALE_PROCESSING_ERROR', message: 'No se pudo completar la venta', operationId: sale.operationId, ventaId: sale.ventaId, cajaMovimientoId: sale.cajaMovimientoId, stockUpdates: sale.stockUpdates || [] } }];
}
return [{ json: { ok: true, ventaId: sale.ventaId, operationId: sale.operationId, total: sale.total, subtotal: sale.subtotal, discountAmount: sale.discountAmount, change: sale.change, idempotent: false } }];

const failed = $json || {};
return [{ json: {
  ok: false,
  operationId: failed.operationId || null,
  ventaId: failed.ventaId || null,
  cajaMovimientoId: failed.cajaMovimientoId || null,
  stockUpdates: Array.isArray(failed.stockUpdates) ? failed.stockUpdates : [],
  failedStep: failed.failedStep || 'UNKNOWN',
  error: failed.error || 'SALE_PROCESSING_ERROR',
  message: failed.message || 'No se pudo completar la venta'
} }];

const rollback = $items('PrepararRollback')[0]?.json || {};
if (!Array.isArray(rollback.stockUpdates) || rollback.stockUpdates.length === 0) {
  return [{ json: { ...rollback, skipStockRestore: true } }];
}
return rollback.stockUpdates.map((update) => ({ json: { id: update.id, 'Stock Actual': update.stockBefore } }));

const rollback = $items('PrepararRollback')[0]?.json || {};
if (!rollback.cajaMovimientoId) {
  return [{ json: { ...rollback, skipCajaCancel: true } }];
}
return [{ json: { id: rollback.cajaMovimientoId, estado: 'ANULADO', motivo: `Anulado automaticamente por rollback de venta ${rollback.operationId || ''}` } }];

const rollback = $items('PrepararRollback')[0]?.json || {};
if (!rollback.ventaId) {
  return [{ json: { ...rollback, skipVentaMark: true } }];
}
return [{ json: { id: rollback.ventaId, Estado: 'ROLLBACK_PENDIENTE' } }];
